276	// decode parses a JSON request body strictly; on failure it writes the error
277	// response and returns false.
278	func decode(w http.ResponseWriter, r *http.Request, target any) bool {
279		decoder := json.NewDecoder(r.Body)
280		decoder.DisallowUnknownFields()
281		if err := decoder.Decode(target); err != nil {
282			respondError(w, &entitlements.Error{
283				Code:    entitlements.CodeInvalidRequest,
284				Message: "request body must be a JSON object with the documented fields",
285			})
286			return false
287		}
288		return true
289	}
290	
291	// errorStatus maps stable domain error codes to HTTP statuses.
292	var errorStatus = map[string]int{
293		entitlements.CodeInvalidRequest:          http.StatusBadRequest,
294		entitlements.CodeEntitlementExists:       http.StatusConflict,
295		entitlements.CodeEntitlementNotFound:     http.StatusNotFound,
296		entitlements.CodeEntitlementNotActive:    http.StatusUnprocessableEntity,
297		entitlements.CodeInsufficientQuota:       http.StatusUnprocessableEntity,
298		entitlements.CodeReservationNotFound:     http.StatusNotFound,
299		entitlements.CodeReservationParamChanged: http.StatusConflict,
300		entitlements.CodeReservationSettled:      http.StatusConflict,
301		entitlements.CodeReservationNotConfirmed: http.StatusUnprocessableEntity,
302		entitlements.CodeReservationReversed:     http.StatusConflict,
303		entitlements.CodeAdjustmentParamChanged:  http.StatusConflict,
304		entitlements.CodeRescheduleParamChanged:  http.StatusConflict,
305		entitlements.CodeSeatAdjustmentChanged:   http.StatusConflict,
306	}
307	
308	func respondError(w http.ResponseWriter, err error) {
309		var domainErr *entitlements.Error
310		if !errors.As(err, &domainErr) {
311			respondJSON(w, http.StatusInternalServerError, map[string]any{
312				"error": map[string]string{"code": "internal", "message": "internal server error"},
313			})
314			return
315		}
316		status, ok := errorStatus[domainErr.Code]
317		if !ok {
318			respondJSON(w, http.StatusInternalServerError, map[string]any{
319				"error": map[string]string{"code": "internal", "message": "internal server error"},
320			})
321			return
322		}
323		respondJSON(w, status, map[string]any{
324			"error": map[string]string{"code": domainErr.Code, "message": domainErr.Message},
325		})
326	}
327	
328	func respondJSON(w http.ResponseWriter, status int, body any) {
329		encoded, err := json.Marshal(body)
330		if err != nil {
331			respond(w, http.StatusInternalServerError, `{"error":{"code":"internal","message":"internal server error"}}`)
332			return
333		}
334		respond(w, status, string(encoded))
335	}
336	
337	func respond(w http.ResponseWriter, status int, body string) {
338		w.Header().Set("Content-Type", "application/json")
339		w.Header().Set("Cache-Control", "no-store")
340		w.WriteHeader(status)
341		_, _ = w.Write([]byte(body + "\n"))
342	}
