1358		wantCode(t, err, CodeInsufficientQuota)
1359		view, _ := store.GetView(ctx, id)
1360		if view.SeatsTotal != 60 || len(view.SeatAdjustments) != 1 {
1361			t.Fatalf("blocked decrease changed state: %+v", view)
1362		}
1363	
1364		// Releasing the held 30 frees them for recovery; the confirmed 30 stay
1365		// allocated, so the floor drops to 30.
1366		if _, err := store.SettleReservation(ctx, id, "res-hold", ActionRelease); err != nil {
1367			t.Fatalf("release: %v", err)
1368		}
1369		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-cut-2", -20); err != nil {
1370			t.Fatalf("decrease after release: %v", err)
1371		}
1372		view, _ = store.GetView(ctx, id)
1373		if view.SeatsTotal != 40 || len(view.SeatAdjustments) != 2 {
1374			t.Fatalf("seat state after release: %+v", view)
1375		}
1376	
1377		// A corrective reversal leaves the original confirmation in place, so
1378		// those 30 seats still count as allocated to the department.
1379		if _, _, err := store.ReverseReservation(ctx, id, "res-used", "corr-1"); err != nil {
1380			t.Fatalf("reverse: %v", err)
1381		}
1382		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-cut-3", -11); err == nil {
1383			t.Fatalf("decrease below a still-confirmed reservation should fail")
1384		} else {
1385			wantCode(t, err, CodeInsufficientQuota)
1386		}
1387		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-cut-4", -10); err != nil {
1388			t.Fatalf("decrease to the confirmed floor should be allowed: %v", err)
1389		}
1390		view, _ = store.GetView(ctx, id)
1391		if view.SeatsTotal != 30 {
1392			t.Fatalf("seat floor after reversal: %+v", view)
1393		}
1394	}
