1465	func TestConcurrentSeatAdjustmentsApplyOnce(t *testing.T) {
1466		store := testStore(t)
1467		id := createSeatEntitlement(t, store, 1000, 1000)
1468		ctx := context.Background()
1469	
1470		const workers = 8
1471		var wg sync.WaitGroup
1472		results := make(chan error, workers*3)
1473		for w := 0; w < workers; w++ {
1474			wg.Add(1)
1475			go func(w int) {
1476				defer wg.Done()
1477				sid := fmt.Sprintf("seat-%d", w)
1478				// Each worker submits one increase, replays it, then submits a
1479				// decrease; replays and first submissions race across workers.
1480				_, _, err := store.CreateSeatAdjustment(ctx, id, sid, 5)
1481				results <- err
1482				_, _, err = store.CreateSeatAdjustment(ctx, id, sid, 5)
1483				results <- err
1484				_, _, err = store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-back-%d", w), -2)
1485				results <- err
1486			}(w)
