1500			t.Fatalf("concurrent seat adjustments broke state: %+v", view)
1501		}
1502		var summed int64
1503		for _, sa := range view.SeatAdjustments {
1504			summed += sa.Delta
1505		}
1506		if summed != workers*3 || view.SeatsTotal != 1000+summed {
