1511	func TestConcurrentSeatAdjustmentsAndReservations(t *testing.T) {
1512		store := testStore(t)
1513		id := createSeatEntitlement(t, store, 1000, 5000)
1514		ctx := context.Background()
1515	
1516		const workers = 8
1517		var wg sync.WaitGroup
1518		errs := make(chan error, workers*4)
1519		for w := 0; w < workers; w++ {
1520			wg.Add(1)
1521			go func(w int) {
1522				defer wg.Done()
1523				rid := fmt.Sprintf("res-%d", w)
1524				if _, _, err := store.CreateReservation(ctx, id, rid, "dept-a", 5); err != nil {
1525					errs <- err
1526					return
1527				}
1528				// Seat allocations and recoveries interleave with reservation
1529				// lifecycle operations on the same row lock.
1530				if _, _, err := store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-up-%d", w), 10); err != nil {
1531					errs <- err
1532				}
1533				if w%2 == 0 {
1534					_, _ = store.SettleReservation(ctx, id, rid, ActionConfirm)
1535				} else {
1536					_, _ = store.SettleReservation(ctx, id, rid, ActionRelease)
1537				}
1538				// 5 seats per worker stay allocated when confirmed, so recovering
1539				// the 10 just added per worker is always feasible.
1540				if _, _, err := store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-down-%d", w), -10); err != nil {
1541					errs <- err
1542				}
1543			}(w)
1544		}
1545		wg.Wait()
1546		close(errs)
1547		for err := range errs {
1548			t.Fatalf("unexpected concurrent failure: %v", err)
1549		}
1550		view, err := store.GetView(ctx, id)
1551		if err != nil {
1552			t.Fatalf("view: %v", err)
1553		}
1554		var allocated int64
1555		for _, r := range view.Reservations {
1556			if r.Status != StatusReleased {
1557				allocated += r.Amount
1558			}
1559		}
1560		if view.SeatsTotal != 1000 || view.SeatsTotal < allocated {
1561			t.Fatalf("seat invariant violated: seats=%d allocated=%d view=%+v",
1562				view.SeatsTotal, allocated, view)
1563		}
1564	}
