1566	func TestSeatAdjustmentsSurviveReconnection(t *testing.T) {
1567		store := testStore(t)
1568		id := createSeatEntitlement(t, store, 100, 100)
1569		ctx := context.Background()
1570		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-1", 50); err != nil {
1571			t.Fatalf("seat increase: %v", err)
1572		}
1573		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-2", -20); err != nil {
1574			t.Fatalf("seat decrease: %v", err)
1575		}
1576		if _, _, err := store.CreateReservation(ctx, id, "res-1", "dept-a", 30); err != nil {
1577			t.Fatalf("reserve: %v", err)
1578		}
1579	
1580		// A fresh pool over the same database simulates a service restart.
1581		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
1582		if err != nil {
1583			t.Fatalf("reconnect: %v", err)
1584		}
1585		defer pool.Close()
1586		restarted := NewStore(pool)
1587		view, err := restarted.GetView(ctx, id)
1588		if err != nil {
1589			t.Fatalf("view after restart: %v", err)
1590		}
1591		if view.SeatsTotal != 130 || len(view.SeatAdjustments) != 2 {
1592			t.Fatalf("seat state lost across restart: %+v", view)
1593		}
1594		if view.SeatAdjustments[0].SeatTotal != 150 || view.SeatAdjustments[1].SeatTotal != 130 {
1595			t.Fatalf("cumulative totals lost across restart: %+v", view.SeatAdjustments)
1596		}
1597		if len(view.Reservations) != 1 || view.Reservations[0].DepartmentID != "dept-a" {
1598			t.Fatalf("department lost across restart: %+v", view.Reservations)
1599		}
1600		// The identifier is still replayed, not re-applied; the allocation floor
1601		// still protects departments after the restart.
1602		replay, created, err := restarted.CreateSeatAdjustment(ctx, id, "seat-2", -20)
1603		if err != nil || created || replay.SeatTotal != 130 {
1604			t.Fatalf("seat adjustment replay after restart: %+v created=%v err=%v", replay, created, err)
1605		}
1606		_, _, err = restarted.CreateSeatAdjustment(ctx, id, "seat-crowd", -101)
1607		wantCode(t, err, CodeInsufficientQuota)
