		go func(w int) {
			defer wg.Done()
			aid := fmt.Sprintf("adj-%d", w)
			// Each worker submits one increase and replays it; the replay
			// races the first submission of other workers.
			_, _, err := store.CreateAdjustment(ctx, id, aid, 5, past)
